import json,sys
BMPNULL=(1<<22)-1
HOPMAX=(1<<22)-2
class Bad(Exception):pass
def norm(a,l):
 if l==0:return 0
 return (a>>(128-l))<<(128-l)
def field(im,s,c,off,width):
 w=int(im['banks'][s][c//2],16);base=128 if c&1 else 0
 return (w>>(base+off))&((1<<width)-1)
def cellzero(im,s,c):
 w=int(im['banks'][s][c//2],16);base=128 if c&1 else 0
 return (w>>base)&((1<<128)-1)==0
def setbits(base,depth,val,n):
 for i in range(n):
  if (val>>(n-1-i))&1: base |= 1<<(127-(depth+i))
 return base
def indep(im):
 cells=im['cells'];banks=im['banks']
 for s in range(11):
  if len(banks[s])!=(cells[s]+1)//2:raise Bad('bank len')
 prefixes={} # (len,addr)->hop
 nodes=[];seen=set()
 def parse(loc,origin,key,depth,region,parent_stage,bulk_parent):
  s,c=loc
  if not(0<=s<=10 and 0<=c<cells[s]):raise Bad('loc')
  if (s,c) in seen:raise Bad('dup node')
  seen.add((s,c))
  typ=field(im,s,c,0,3)
  if typ not in (1,2,3,4,5):raise Bad('type')
  if typ in (2,3,5) and c%2:raise Bad('align')
  bmp=field(im,s,c,3,22)
  n={'s':s,'c':c,'type':typ,'depth':depth,'region':region,'bmp':bmp,'bulk_parent':bulk_parent,'children':[],'locals':[],'inline':[]}
  ni=len(nodes);nodes.append(n)
  def addprefix(addr,length,hop):
   addr=norm(addr,length)
   if length<0 or length>128:raise Bad('plen')
   if length<depth:raise Bad('len<depth')
   # belongs region
   if norm(addr,depth)!=norm(region,depth):raise Bad('region')
   if origin==0:
    if not(0<=length<=16):raise Bad('own0')
   elif origin==16:
    if not(17<=length<=64) or (addr>>112)!=key:raise Bad('own16')
   else:
    if not(65<=length<=128) or (addr>>64)!=key:raise Bad('own64')
   if (length,addr) in prefixes:raise Bad('duplicate prefix')
   prefixes[(length,addr)]=hop
  if typ in (4,5):
   resoff,resw=(119,9) if typ==4 else (213,43)
   if field(im,s,c,resoff,resw):raise Bad('res')
   cnt=1 if typ==4 else 2
   for i in range(cnt):
    off=25+94*i;frag=field(im,s,c,off,64);rel=field(im,s,c,off+64,8);hop=field(im,s,c,off+72,22)
    if hop==BMPNULL:raise Bad('hopnull')
    if origin==0:
     if rel>16:raise Bad('rel0')
     length=rel;addr=frag
     if frag & ~((1<<64)-1 if rel==0 else (((1<<rel)-1)<<(64-rel))):raise Bad('host0')
    elif origin==16:
     if not(1<=rel<=48):raise Bad('rel16')
     if frag & 0xffff:raise Bad('frag16')
     v=frag>>16
     if v & ~(((1<<rel)-1)<<(48-rel)):raise Bad('host16')
     length=16+rel;addr=(key<<112)|(v<<64)
    else:
     if not(1<=rel<=64):raise Bad('rel64')
     length=64+rel;addr=(key<<64)|frag
     if frag & ~((1<<64)-1 if rel==64 else (((1<<rel)-1)<<(64-rel))):raise Bad('host64')
    addprefix(addr,length,hop);n['inline'].append((addr,length,hop))
  else:
   resoff,resw=(127,1) if typ in(1,2) else (249,7)
   if field(im,s,c,resoff,resw):raise Bad('res')
   bid=field(im,s,c,25,16);nibase=field(im,s,c,41,22)
   if bid>=len(im['bitmaps']):raise Bad('bid')
   pattern=int(im['bitmaps'][bid],16)
   if pattern&1:raise Bad('bit0')
   lc=pattern.bit_count()
   if lc==0:
    if nibase!=0:raise Bad('nibase0')
   else:
    if nibase+lc>len(im['nexthops']):raise Bad('nirange')
    ordi=0
    for pos in range(1,64):
     if pattern>>pos&1:
      l=0;base=1
      while l<5 and pos>=base*2:l+=1;base*=2
      v=pos-base;length=depth+l
      if origin==0:
       if length>16:raise Bad('own0')
      elif origin==16:
       if length<17 or length>64:raise Bad('own16l')
      else:
       if length<65 or length>128:raise Bad('own64l')
      addr=setbits(region,depth,v,l);addr=norm(addr,length)
      hop=im['nexthops'][nibase+ordi];ordi+=1
      addprefix(addr,length,hop);n['locals'].append((pos,length,addr,hop))
   # child records
   if typ in (1,2):
    slots=2 if typ==1 else 6;off0=63
    present=[];sawabs=False
    for i in range(slots):
     raw=field(im,s,c,off0+32*i,32);k=raw&63;st=(raw>>6)&15;ce=(raw>>10)&0x3fffff
     if k==0 and st==15 and ce==0:sawabs=True;continue
     if sawabs:raise Bad('absent order')
     if st>10 or ce>131071 or st>=s:raise Bad('child loc')
     if present and present[-1][0]>=k:raise Bad('child order')
     present.append((k,st,ce))
    if typ==1 and len(present)>2:raise Bad('t1 count')
    if typ==2 and not(3<=len(present)<=6):raise Bad('t2 count')
    for k,st,ce in present:
     childreg=setbits(region,depth,k,6)
     ci=parse((st,ce),origin,key,depth+6,childreg,s,False);n['children'].append(ci)
   else:
    bm=field(im,s,c,63,64);base=field(im,s,c,127,22);bstage=field(im,s,c,149,4)
    direct=[];sawabs=False
    for i in range(3):
     raw=field(im,s,c,153+32*i,32);k=raw&63;st=(raw>>6)&15;ce=(raw>>10)&0x3fffff
     if k==0 and st==15 and ce==0:sawabs=True;continue
     if sawabs:raise Bad('direct order')
     if st>10 or ce>131071 or st>=s:raise Bad('direct loc')
     if direct and direct[-1][0]>=k:raise Bad('direct key order')
     direct.append((k,st,ce))
    bcnt=bm.bit_count()
    if len(direct)>3:raise Bad('direct max')
    if bcnt>0:
     if bcnt<4:raise Bad('bulk min')
     if bstage>10 or bstage>=s or base%2:raise Bad('bulk stage/base')
     if base+2*bcnt>cells[bstage]:raise Bad('bulk range')
    tot=len(direct)+bcnt
    if not(7<=tot<=64):raise Bad('type3 count')
    childkeys=set()
    for k,st,ce in direct:childkeys.add(k)
    for k,st,ce in direct:
     childreg=setbits(region,depth,k,6)
     ci=parse((st,ce),origin,key,depth+6,childreg,s,False);n['children'].append(ci)
    ordi=0
    for k in range(64):
     if bm>>k&1:
      if k in childkeys:raise Bad('direct bulk overlap')
      childkeys.add(k);ce=base+2*ordi;ordi+=1
      childreg=setbits(region,depth,k,6)
      ci=parse((bstage,ce),origin,key,depth+6,childreg,s,True);n['children'].append(ci)
   # subtree count
   sc=lc+sum(nodes[ch]['count'] for ch in n['children'])
   if typ in (4,5):sc=len(n['inline'])
   if sc<=0 or sc>8192:raise Bad('subtree count')
   n['count']=sc
  return ni
 # roots
 root=None
 if im['root'] is not None:
  root=parse(tuple(im['root']),0,0,0,0,-1,False)
 for f in im['front16']:
  key=int(f[0],16);region=key<<112
  parse((f[1],f[2]),16,key,16,region,-1,False)
 for f in im['front64']:
  key=int(f[0],16);region=key<<64
  parse((f[1],f[2]),64,key,64,region,-1,False)
 # coverage
 occ=[[0]*cells[s] for s in range(11)]
 for n in nodes:
  ext=2 if n['bulk_parent'] else (1 if n['type'] in (1,4) else 2)
  if n['c']+ext>cells[n['s']]:raise Bad('extent')
  for j in range(ext):
   if occ[n['s']][n['c']+j]:raise Bad('overlap')
   occ[n['s']][n['c']+j]=1
  if n['bulk_parent'] and n['type'] in (1,4) and not cellzero(im,n['s'],n['c']+1):raise Bad('bulk pad')
 for s in range(11):
  if any(x!=1 for x in occ[s]):raise Bad('hole')
  if cells[s]%2 and not cellzero(im,s,cells[s]):raise Bad('final pad')
 # type counts
 for n in nodes:
  cnt=len(n['children'])
  if n['type']==4:
   if n['count']!=1 or cnt:raise Bad('t4')
  elif n['type']==5:
   if n['count']!=2 or cnt or n['inline'][0][:2]==n['inline'][1][:2]:raise Bad('t5')
  else:
   if n['count']<3:raise Bad('small branch')
   if n['type']==1 and cnt>2:raise Bad('t1c')
   if n['type']==2 and not(3<=cnt<=6):raise Bad('t2c')
   if n['type']==3 and not(7<=cnt<=64):raise Bad('t3c')
 # front complete
 need=any(l<=16 for l,a in prefixes)
 if need != (im['root'] is not None):raise Bad('root presence')
 exp16={a>>112 for (l,a) in prefixes if 17<=l<=64}
 exp64={a>>64 for (l,a) in prefixes if l>64}
 if [int(f[0],16) for f in im['front16']]!=sorted(exp16):raise Bad('front16 complete')
 if [int(f[0],16) for f in im['front64']]!=sorted(exp64):raise Bad('front64 complete')
 # NI tiling
 owner=[-1]*len(im['nexthops'])
 for idx,n in enumerate(nodes):
  if n['type'] in (4,5) or not n['locals']:continue
  bid=field(im,n['s'],n['c'],25,16);bidx=field(im,n['s'],n['c'],41,22)
  cnt=len(n['locals'])
  for j in range(cnt):
   if owner[bidx+j]!=-1:raise Bad('ni overlap')
   owner[bidx+j]=idx
 if any(x==-1 for x in owner):raise Bad('ni hole')
 # patterns used
 used=set()
 for n in nodes:
  if n['type'] in (1,2,3):used.add(field(im,n['s'],n['c'],25,16))
 if used!=set(range(len(im['bitmaps']))):raise Bad('pattern unused')
 # bmps
 for n in nodes:
  expd=BMPNULL
  for k in range(n['depth'],-1,-1):
   a=norm(n['region'],k)
   if (k,a) in prefixes:expd=prefixes[(k,a)];break
  if n['bmp']!=expd:raise Bad(f"bmp node {n['s']},{n['c']} got {n['bmp']} exp {expd}")
 return len(prefixes),len(nodes)
if __name__=='__main__':
 im=json.load(open(sys.argv[1]));print(indep(im))
